import 'dotenv/config';
import { defineConfig } from 'prisma/config';

const databaseUrl = process.env['DATABASE_URL'];

if (!databaseUrl) {
  throw new Error('DATABASE_URL is required.');
}

const databaseSchema = process.env['DATABASE_SCHEMA']?.trim();

if (!databaseSchema) {
  throw new Error('DATABASE_SCHEMA is required.');
}

if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(databaseSchema)) {
  throw new Error('DATABASE_SCHEMA must be a valid PostgreSQL identifier.');
}

if (databaseSchema === 'dsp_pms_stg') {
  const postgresOverride = Object.entries(process.env).find(
    ([name, value]) => /^PG[A-Z0-9_]*$/i.test(name) && Boolean(value?.trim()),
  );
  if (postgresOverride) {
    throw new Error(
      `${postgresOverride[0]} is forbidden for staging Prisma migrations. Use the guarded deploy command with its canonical DATABASE_URL instead.`,
    );
  }
}

const migrationUrl = new URL(
  databaseUrl.replace(/^postgres(?:ql)?\+asyncpg:\/\//i, 'postgresql://'),
);

if (databaseSchema === 'dsp_pms_stg') {
  const forbiddenQueryParameter = [...migrationUrl.searchParams.keys()].find(
    (name) =>
      [
        'host',
        'hostaddr',
        'options',
        'port',
        'search_path',
        'service',
        'servicefile',
        'user',
      ].includes(name.toLowerCase()),
  );
  if (forbiddenQueryParameter) {
    throw new Error(
      `DATABASE_URL query parameter ${forbiddenQueryParameter} is forbidden for staging Prisma migrations.`,
    );
  }
}

migrationUrl.searchParams.set('schema', databaseSchema);

const sslMode = process.env['DATABASE_SSL_MODE']?.trim();

if (sslMode) {
  migrationUrl.searchParams.set('sslmode', sslMode);
}

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
  },
  datasource: {
    url: migrationUrl.toString(),
  },
});
